-- =====================================================================
-- طابوني برو — إعداد قاعدة بيانات الموقع ولوحة الإدارة (v1.22)
-- شغّل الملف مرة وحدة: Supabase ← SQL Editor ← New query ← الصق ← Run
-- آمن للتشغيل بمشروع VIP الحالي: كل الجداول بتبلّش بـ site_ وما بيلمس جداول VIP.
-- =====================================================================

-- 1) جدول الأدمن + دالة فحص الصلاحية
create table if not exists public.site_admins (
  user_id uuid primary key references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);
alter table public.site_admins enable row level security;
-- (بدون policies: ما حدا بيقدر يقرأ أو يعدّل الجدول من المتصفح)

create or replace function public.is_site_admin()
returns boolean language sql stable security definer set search_path = public
as $$ select exists (select 1 from public.site_admins where user_id = auth.uid()) $$;
grant execute on function public.is_site_admin() to anon, authenticated;

-- 2) الجداول
create table if not exists public.site_products (
  id          bigint generated by default as identity primary key,
  title       text not null,
  description text not null default '',
  category    text not null default 'baked' check (category in ('pizza','baked','meals','workshop')),
  price       numeric(10,2) not null default 0 check (price >= 0),
  compare_at  numeric(10,2) check (compare_at is null or compare_at >= 0),
  variants    jsonb not null default '[]'::jsonb,
  images      jsonb not null default '[]'::jsonb,
  status      text not null default 'active' check (status in ('active','draft')),
  featured    boolean not null default false,
  sort        int not null default 0,
  updated_at  timestamptz not null default now()
);
create table if not exists public.site_faqs (
  id         bigint generated by default as identity primary key,
  q          text not null,
  a          text not null default '',
  visible    boolean not null default true,
  sort       int not null default 0,
  updated_at timestamptz not null default now()
);
create table if not exists public.site_settings (
  id         int primary key default 1 check (id = 1),
  data       jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);

-- 3) الصلاحيات (RLS): الكل بيقرأ المحتوى الظاهر، الأدمن بس بيعدّل
alter table public.site_products enable row level security;
alter table public.site_faqs     enable row level security;
alter table public.site_settings enable row level security;

drop policy if exists "site_products read"  on public.site_products;
drop policy if exists "site_products admin" on public.site_products;
create policy "site_products read"  on public.site_products for select using (status = 'active' or public.is_site_admin());
create policy "site_products admin" on public.site_products for all using (public.is_site_admin()) with check (public.is_site_admin());

drop policy if exists "site_faqs read"  on public.site_faqs;
drop policy if exists "site_faqs admin" on public.site_faqs;
create policy "site_faqs read"  on public.site_faqs for select using (visible or public.is_site_admin());
create policy "site_faqs admin" on public.site_faqs for all using (public.is_site_admin()) with check (public.is_site_admin());

drop policy if exists "site_settings read"  on public.site_settings;
drop policy if exists "site_settings admin" on public.site_settings;
create policy "site_settings read"  on public.site_settings for select using (true);
create policy "site_settings admin" on public.site_settings for all using (public.is_site_admin()) with check (public.is_site_admin());

grant select on public.site_products, public.site_faqs, public.site_settings to anon, authenticated;
grant insert, update, delete on public.site_products, public.site_faqs, public.site_settings to authenticated;

-- 4) مخزن الصور (عام للقراءة، الأدمن بس بيرفع/بيحذف) — حد 5MB لكل صورة
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('site-images', 'site-images', true, 5242880, array['image/jpeg','image/png','image/webp'])
on conflict (id) do update set public = true, file_size_limit = 5242880, allowed_mime_types = array['image/jpeg','image/png','image/webp'];

drop policy if exists "site-images admin insert" on storage.objects;
drop policy if exists "site-images admin update" on storage.objects;
drop policy if exists "site-images admin delete" on storage.objects;
create policy "site-images admin insert" on storage.objects for insert to authenticated with check (bucket_id = 'site-images' and public.is_site_admin());
create policy "site-images admin update" on storage.objects for update to authenticated using (bucket_id = 'site-images' and public.is_site_admin());
create policy "site-images admin delete" on storage.objects for delete to authenticated using (bucket_id = 'site-images' and public.is_site_admin());

-- 5) تعبئة المحتوى الحالي (مرة وحدة — إذا الجداول فاضية)
insert into public.site_products (id, title, description, category, price, compare_at, variants, images, status, featured, sort)
select * from (values
(2, $tp$بيتزا نابولي (مارغاريتا)$tp$, $tp$<p>بيتزا نابولي بطابوني برو<br>عجينة بتخمير طويل من 36–72 ساعة، خفيفة، طرية، ومقرمشة بتحميصة غير شكل بالطابون.<br>أطراف منتفخة, جبنه موتزاريلا وصوص بندورة مع ريحان بيعطوها طعم اصلي كأنك بنابولي<br>هاي هي ملكة البيتزا بالعالم</p>$tp$, 'pizza', 50, 55, $tp$[{"label": "شخصية", "price": 40, "compare_at": null}, {"label": "شخصية +", "price": 50, "compare_at": null}, {"label": "وسط", "price": 60, "compare_at": null}]$tp$::jsonb, $tp$[{"src": "assets/products/margherita-1.jpg"}, {"src": "assets/products/margherita-2.jpg"}]$tp$::jsonb, 'active', true, 1),
(1, $tp$بيتزا كنافه$tp$, $tp$<p>بيتزا كنافة بطابوني برو</p><p>عجينة نابولي محمّصة على نار الطابون، مغطّاة بجبنة موتزاريلا وطبقة شعر كنافة ذهبية مقرمشة، بطعم حلو متوازن بين القرمشة والطراوة. تجربة فريدة وحصرية بطابع فاخر ومميز.</p>$tp$, 'pizza', 50, 55, $tp$[{"label": "شخصية", "price": 40, "compare_at": null}, {"label": "شخصية +", "price": 50, "compare_at": null}, {"label": "وسط", "price": 60, "compare_at": null}]$tp$::jsonb, $tp$[{"src": "assets/products/kunafa-1.jpg"}]$tp$::jsonb, 'active', true, 2),
(3, $tp$بيتسا نابولي ميكس$tp$, $tp$<p>تقدم بيتزا نابولي بالطريقة الفلسطينية مزيجاً مثالياً من النكهات التقليدية والتقنيات الإيطالية الأصيلة. تتميز هذه البيتزا بعجينة رقيقة وهشة تُخبز على حرارة عالية لتعطيها القرمشة المثالية والقوام الخفيف. تُغطى الصلصة الطازجة المصنوعة من الطماطم الناضجة والثوم المعطر وزيت الزيتون، تُزيّن بجبن الموزاريلا الطازج الذي يذوب بشكل مثالي ليخلق قواماً كريميًا لذيذًا.</p><p>تضيف اللمسات الفلسطينية نكهة فريدة من نوعها، حيث تُزين البيتزا بشرائح الزيتون الأسود/الاخضر / الذره وأوراق الريحان الطازجة، يُرش عليها الزعتر البري وزعتر فلسطين الأصيل لإضافة لمسة تقليدية تميزها عن البيتزا العادية.</p>$tp$, 'pizza', 50, 55, $tp$[{"label": "شخصية", "price": 40, "compare_at": null}, {"label": "شخصية +", "price": 50, "compare_at": null}, {"label": "وسط", "price": 60, "compare_at": null}]$tp$::jsonb, $tp$[{"src": "assets/products/napoli-mix-1.jpg"}]$tp$::jsonb, 'active', true, 3),
(4, $tp$خبز قمح(كامل) بالطابون$tp$, $tp$<p>الخبز الفلسطيني بالطابون هو أحد الأطعمة التقليدية التي تحمل في طياتها عبق التاريخ والهوية الثقافية للشعب الفلسطيني. يتميز هذا الخبز بنكهته الفريدة وقوامه الطري والمقرمش في آن واحد، ويعتبر جزءاً أساسياً من التراث الغذائي في فلسطين.</p>$tp$, 'baked', 3, 5, $tp$[]$tp$::jsonb, $tp$[{"src": "assets/products/taboon-bread-1.jpg"}, {"src": "assets/products/taboon-bread-2.jpg"}, {"src": "assets/products/taboon-bread-3.jpg"}, {"src": "assets/products/taboon-bread-4.jpg"}]$tp$::jsonb, 'active', false, 4),
(5, $tp$زعتر بالطابون$tp$, $tp$<p>وجبه فريدة تمزج بين أصالة المطبخ الإيطالي وسحر نكهات الشرق الأوسط مع زعتر على عجينة بيتزا نابولي. تُحضّر هذه الوجبة بعناية باستخدام عجينة بيتزا نابولي التقليدية، المعروفة بقوامها الهش من الخارج والمرن من الداخل، والتي تُخبز على درجة حرارة عالية لتحقق التوازن المثالي بين القرمشة والطراوه.</p><p>تُغمر العجينة بزيت الزيتون الذي يضفي لمسة غنية، ثم تُرش بكمية سخية من الزعتر العطري الطازج أو المجفف، لتضيف نكهة حادة وعطرية تنقلك إلى مروج الزعتر الجبلية. يُمكن تقديم الوجبة كما هي بنكهتها البسيطة والنقية، أو مع إضافة طبقة من الزيتون وجبنة الموزاريلا التي تذوب لتمنحك مزيجًا من القوام والنكهة المثالية.</p><p>هذه الوجبة تعتبر خيارًا مثاليًا لعشاق النكهات المميزة والتجارب الغذائية المبتكرة، حيث تجمع بين عناصر تقليدية من مطبخين مميزين بأسلوب معاصر يرضي جميع الأذواق.</p>$tp$, 'baked', 50, 60, $tp$[]$tp$::jsonb, $tp$[{"src": "assets/products/zaatar-1.jpg"}, {"src": "assets/products/zaatar-2.jpg"}, {"src": "assets/products/zaatar-3.jpg"}]$tp$::jsonb, 'active', false, 5),
(11, $tp$مختارات من الطابون$tp$, $tp$<p><strong>مختارات من الطابون</strong> تقدم تجربة فريدة تجمع بين التراث الشرقي والفلسطيني بالاخص ودمج المذاق الإيطالي الأصيل. خبز الطابون المخبوز على الطريقة الإيطالية يُقدم مع إضافة اللبنة الكريمية وزيت الزيتون مكللًا بالبيض الطازج والزعتر المطحون(دُكّه) لإضفاء نكهة غنية ومتوازنة. كل لقمة تقدم تجربة تجمع بين القوام الهش والنكهة العميقة، في مزيج مثالي من البساطة والفخامة.</p>$tp$, 'baked', 40, 50, $tp$[]$tp$::jsonb, $tp$[{"src": "assets/products/taboon-selection-1.jpg"}, {"src": "assets/products/taboon-selection-2.jpg"}]$tp$::jsonb, 'active', false, 6),
(10, $tp$لحمجين$tp$, $tp$<p><strong>لحم بعجين</strong> بالطريقة الفلسطينية هو طبق تقليدي شهير في المطبخ الفلسطيني، يتكون من عجينة رقيقة تُخبز مع طبقة لذيذة من اللحم المفروم المتبّل بالخضروات والبهارات. يُخبز هذا الطبق في الطابون مما يمنحه نكهة مميزة ومذاقًا فريدًا. يعتبر لحم بعجين وجبة مشبعة ومحبوبة، تُقدم عادةً مع اللبن أو السلطة، وتُعد خيارًا مثاليًا للعشاء أو الغداء.</p>$tp$, 'baked', 70, 80, $tp$[]$tp$::jsonb, $tp$[{"src": "assets/products/lahmajin-1.jpg"}]$tp$::jsonb, 'active', false, 7),
(9, $tp$فوكاتشا ايطاليه$tp$, $tp$<p><strong>الفوكاتشا الإيطالية</strong> هي خبز تقليدي يعود تاريخه إلى العصور الرومانية، ويتميز بقوامه الهش من الخارج والطري من الداخل، نكهته الغنية التي تجمع بين البساطة والتنوع. يتم إعداد الفوكاتشا باستخدام مكونات طبيعية مثل زيت الزيتون، الطحين عالي الجودة، الخميرة، والملح، مع لمسات من الأعشاب الإيطالية العطرية مثل الروزماري والزعتر او جبنة الموزاريلا والريحان مع صلصة البندوره الايطاليه.</p>$tp$, 'baked', 30, 50, $tp$[]$tp$::jsonb, $tp$[{"src": "assets/products/focaccia-1.jpg"}]$tp$::jsonb, 'active', false, 8),
(12, $tp$نوتيلا كالزوني- Nutella Calzone$tp$, $tp$<p>الـ <strong>Calzone شوكولاتة</strong> هو نوع من الحلوى الإيطالية الشهية التي تجمع بين عجينة الكالزوني الشهيرة وشوكولاتة نوتيلا اللذيذة.</p><p>تجمع كالزوني النوتيلا بين الأصالة الإيطالية ومتعة الشوكولاتة في حلوى فاخرة، حيث تُحشى عجينة البيتزا الطرية بنوتيلا الغنية والمكسرات، ثم تُخبز لتصبح ذهبية وهشة من الخارج وناعمة من الداخل. هذه الحلوى هي الخيار المثالي لمن يبحث عن تجربة فريدة تجمع بين النكهات الكلاسيكية والحديثة.</p>$tp$, 'baked', 50, 60, $tp$[]$tp$::jsonb, $tp$[{"src": "assets/products/nutella-calzone-1.jpg"}, {"src": "assets/products/nutella-calzone-2.jpg"}, {"src": "assets/products/nutella-calzone-3.jpg"}, {"src": "assets/products/nutella-calzone-4.jpg"}]$tp$::jsonb, 'active', false, 9),
(8, $tp$عجينه نابولي$tp$, $tp$<p>عجينة بيتزا نابولي هي جوهر المطبخ الإيطالي التقليدي، وهي سر القوام الفريد الذي يميز هذا النوع من البيتزا عن غيرها. تُحضّر بعناية فائقة باستخدام مكونات بسيطة، لكنها تحتاج إلى إتقان فن التخمير الطويل للحصول على عجينة خفيفة ومطاطية.</p>$tp$, 'baked', 15, 20, $tp$[]$tp$::jsonb, $tp$[{"src": "assets/products/napoli-dough-1.jpg"}, {"src": "assets/products/napoli-dough-2.jpg"}, {"src": "assets/products/napoli-dough-3.jpg"}, {"src": "assets/products/napoli-dough-4.jpg"}, {"src": "assets/products/napoli-dough-5.jpg"}]$tp$::jsonb, 'active', false, 10),
(6, $tp$شوارما بالطابون$tp$, $tp$<p><strong>شاورما لحم الحبش والخروف بالطابون</strong> هي وجبة شهية ومميزة من المطبخ الشرقي، تُحضّر باستخدام لحم الحبش ودهن الخروف المتبل بشكل خاص والمشوي في الطابون التقليدي، مما يضفي عليها نكهة مميزة ودخانية. يتم تتبيل شرائح لحم الحبش بتوليفة من البهارات العطرية، الزيت، الثوم، والليمون، ثم تُترك لتتشرب النكهات. بعد ذلك، تُشوى الشرائح في الطابون حتى تنضج وتتحمر بشكل مثالي. تُقدّم الشاورما في خبز الطابون الطازج مع مزيج من السلطات الطازجة، الطحينة، والمخللات، مما يجعلها وجبة متكاملة ولذيذة ترضي جميع الأذواق</p>$tp$, 'meals', 90, 110, $tp$[]$tp$::jsonb, $tp$[{"src": "assets/products/shawarma-1.jpg"}]$tp$::jsonb, 'active', false, 11),
(7, $tp$صدر دجاج وخضروات بالطابون$tp$, $tp$<p><strong>صدور الدجاج المشوية بالطابون والخضروات الطازجة- </strong>وجبة مميزة وشهية تجمع بين النكهة الشرقية التقليدية والصحة يتم إعداد هذه الوجبة بعناية باستخدام صدور الدجاج الطرية، المتبلة بتوابل طبيعية مختارة بعناية لتعزيز النكهة. يتم شوي الدجاج في الطابون، مما يضفي عليه مذاقًا مدخنًا ومقرمشًا من الخارج مع احتفاظه بالطراوه من الداخل.</p><p>تقدم وجبة الدجاج مع تشكيلة من الخضروات الطازجة مثل البطاطا، الجزر، الكوسا، الفلفل الحلو والبصل، المشويه مع لمسة من زيت الزيتون في الطابون، مما يمنحها قوامًا مقرمشًا ونكهة غنية. هذه الوجبة مثالية لعشاق الطعام الصحي والمذاق الفاخر.</p>$tp$, 'meals', 80, 100, $tp$[]$tp$::jsonb, $tp$[{"src": "assets/products/chicken-veg-1.jpg"}]$tp$::jsonb, 'active', false, 12),
(13, $tp$ورشة طابون$tp$, $tp$<p><strong>تجربة مميزة تجمع بين التراث الاصيل, بيتسا نابولي والإبداع </strong></p><p>ستخوض تجربة فريدة تجمع بين الخبز التقليدي والإبداع الحديث. خلال هذه الورشة، ستتعلم كيفية تحضير أطباق ومخبوزات مميزة باستخدام الطابون وتشمل:</p><p><strong>تدريب عملي</strong> على إعداد الأطباق باستخدام طابون الحطب والغاز.</p><p><strong>تعلم تقنيات العجينة</strong> المثالية مع شرح مفصل عن التخمير، الطهي على درجات حرارة عالية، وكيفية تحقيق القوام المثالي.</p><p><strong> نصائح</strong>للحصول على أفضل نكهة وقرمشة، بالإضافة إلى تجربة أجواء الطهي التقليدي.</p><p><strong>تحضير بيتزا نابولي الأصلية:</strong> من إعداد العجينة المثالية إلى خبزها في الطابون، لتكتشف سر القرمشة والنكهة الغنية التي تمنحها حرارة الطابون العالية.</p><p><strong>خبز الطابون التقليدي:</strong> استمتع بتجربة صنع الخبز بالطريقة التقليدية التي تعكس تاريخ وثقافة الطهي في منطقتنا.</p><p><strong>تذوق الأطباق التي تحضرها مع المجموعة في جلسة ختامية ممتعة</strong></p>$tp$, 'workshop', 350, 400, $tp$[]$tp$::jsonb, $tp$[{"src": "assets/products/taboon-workshop-1.jpg"}, {"src": "assets/products/taboon-workshop-2.jpg"}]$tp$::jsonb, 'active', true, 13)
) v(id, title, description, category, price, compare_at, variants, images, status, featured, sort)
where not exists (select 1 from public.site_products);
select setval(pg_get_serial_sequence('public.site_products','id'), greatest((select max(id) from public.site_products), 1));

insert into public.site_faqs (id, q, a, visible, sort)
select * from (values
(1, $tp$لماذا لا يتوفر التوصيل لبيتزا نابولي بالطابون؟$tp$, $tp$نحن نحرص على تقديم تجربة بيتزا نابولي بالطابون كما يجب أن تكون، ساخنة وطازجة، مباشرة من الطابون إلى طاولتك. بيتزا نابولي تعتمد على قوام هش وحواف مقرمشة، وهو ما يتغير بشكل كبير عند التوصيل بسبب التكثيف وفقدان الحرارة، لذلك نفضل أن يتم تناولها في الحال لضمان أعلى جودة.$tp$, true, 1),
(2, $tp$هل هناك إمكانية استلام البيتزا من المكان؟$tp$, $tp$نعم، نقدم خيار الاستلام من المطعم. يمكنك طلب بيتزا نابولي بالطابون مسبقًا، وستكون جاهزة لاستلامها في الوقت المحدد. نضمن لك أن تكون البيتزا ساخنة وجاهزة للاستمتاع بها فور وصولك.$tp$, true, 2),
(3, $tp$ما الذي يجعل بيتزا نابولي بالطابون فريدة من نوعها؟$tp$, $tp$بيتزا نابولي بالطابون تتميز بمكونات طازجة وعجينة تقليدية مخمرة لمدة 24-72 ساعة، يتم خبزها في حرارة عالية داخل الطابون الذي يضفي عليها نكهة مدخنة وقوامًا مقرمشًا. الطابون يحاكي الطريقة التقليدية لخبز البيتزا في أفران الحطب في نابولي، وهو ما يجعل التجربة فريدة ومختلفة عن البيتزا العادية.$tp$, true, 3),
(4, $tp$هل هناك عروض خاصة للعائلات أو المجموعات؟$tp$, $tp$نعم، لدينا عروض مميزة للعائلات والمجموعات التي ترغب في الاستمتاع ببيتزا نابولي بالطابون. يمكنك الاستفسار عن العروض المتاحة عند الطلب أو الحجز.$tp$, true, 4),
(5, $tp$هل تقدمون أحجام مختلفة من بيتزا نابولي؟$tp$, $tp$نعم، بيتزا نابولي متوفرة بثلاثة أحجام: شخصية (₪40)، شخصية + (₪50) ووسط (₪60). اختر الحجم من بطاقة البيتزا عند الطلب. إذا كانت لديك متطلبات خاصة أو طلبية لمجموعة، تواصل معنا.$tp$, true, 5),
(6, $tp$هل تقدمون ورشات عمل أو دورات تدريبية حول كيفية إعداد بيتزا نابولي؟$tp$, $tp$نعم، نقدم ورشات عمل ودورات تعليمية حول فن إعداد بيتزا نابولي التقليدية، بما في ذلك طريقة تحضير العجينة واستخدام الطابون. هذه الدورات مفتوحة لعشاق الطهي والمبتدئين على حد سواء.$tp$, true, 6)
) v(id, q, a, visible, sort)
where not exists (select 1 from public.site_faqs);
select setval(pg_get_serial_sequence('public.site_faqs','id'), greatest((select max(id) from public.site_faqs), 1));

